const req=$input.first().json?.raw_data||$input.first().json;
const start=req.start_time||new Date(Date.now()-86400000).toISOString();
const end=req.end_time||new Date().toISOString();
return[{json:{case_id:req.case_id||`TL-${Date.now()}`,hosts:req.hosts||[],
  start_time:start,end_time:end,analyst:req.analyst||'unknown'}}];

const params=$('Parse Timeline Request').first().json;
const alerts=$('Query SIEM Alerts').all().map(i=>i.json);
const auth=$('Query Auth Events').all().map(i=>i.json);
// Merge and sort all events chronologically
const all=[...alerts,...auth].sort((a,b)=>new Date(a.event_time)-new Date(b.event_time));
// Group by 5-minute buckets for density analysis
const buckets={};
for(const e of all){
  const bucket=new Date(Math.floor(new Date(e.event_time)/300000)*300000).toISOString();
  if(!buckets[bucket])buckets[bucket]=0;
  buckets[bucket]++;
}
// Find activity spikes (buckets with >5 events = anomalous)
const spikes=Object.entries(buckets).filter(([t,c])=>c>5).map(([t,c])=>({time:t,count:c}));
return[{json:{...params,total_events:all.length,timeline:all.slice(0,50),
  activity_spikes:spikes,spike_count:spikes.length,
  first_event:all[0]?.event_time,last_event:all[all.length-1]?.event_time,
  built_at:new Date().toISOString()}}];

